package studio.jiayu.neoagent;
import android.app.Activity;import android.os.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
final class CaptureContracts {
 static void start(Activity a){TextView label=new TextView(a);label.setText("本机截图间隔检查");label.setTextSize(24);a.setContentView(label);new Handler().postDelayed(()->new Thread(()->run(a)).start(),900);}
 static ControlService.Observation stable(ControlService s,long g)throws Exception{Exception last=null;for(int i=0;i<6;i++){try{return s.observe(true,g);}catch(ControlService.UiChangedException|ControlService.CaptureRetryException transientUi){last=transientUi;Thread.sleep(500);}}throw last;}
 static void run(Activity a){ControlService s=ControlService.instance;JSONObject out=new JSONObject();String before="";try{if(s==null||!s.connected||s.busy())throw new Exception("Service unavailable");before=new Vault(a).get(RoutineAccess.KEY);Config c=new Config();c.endpoint="https://fixture.invalid/v1";c.key="LOCAL_FIXTURE";c.vision=true;new RoutineAccess(a).approve(c,Collections.singletonList(a.getPackageName()));long g=s.ui(()->{s.allowed=a.getPackageName();s.runConfig=c;s.running=true;s.paused=false;s.generation=s.ownership.start();s.runtimeHealth.phase("observing");return s.generation;});ControlService.Observation first=stable(s,g);long firstAt=s.lastScreenshotRequestAt;ControlService.Observation second=stable(s,g);long delta=s.lastScreenshotRequestAt-firstAt;if(first.image==null||second.image==null||second.annotatedImage==null)throw new Exception("Missing native images");if(delta<350)throw new Exception("Capture spacing violated");if(!CaptureRules.retryable(3)||CaptureRules.retryable(6)||CaptureRules.retryable(2))throw new Exception("Wrong error classification");out.put("success",true).put("passed",3).put("request_spacing_ms",delta);}catch(Exception e){try{out.put("success",false).put("failure",e.getMessage());}catch(Exception ignored){}}finally{if(s!=null)s.stop("截图间隔回归结束");try{if(before.isEmpty())new Vault(a).remove(RoutineAccess.KEY);else new Vault(a).put(RoutineAccess.KEY,before);try(FileOutputStream f=a.openFileOutput("capture-contracts.json",0)){f.write(out.put("real_network_calls",0).put("third_party_apps",0).put("sampledAt",System.currentTimeMillis()).toString(2).getBytes("UTF-8"));}}catch(Exception ignored){}a.runOnUiThread(a::finish);}}
}
